type IconProps = {
  name: IconName
  size?: number
  width?: number
  height?: number
}

export function Icon({ name, size = 24, width = size, height = size }: IconProps) {
  return (
    <svg
      width={width}
      height={height}
      viewBox={name === 'page404' 
        ? '0 0 460 304' 
        : name === 'done'
        ? '0 0 77 77' 
        : '0 0 24 24'}
      fill="none"
      stroke="currentColor"
      aria-hidden="true"
    >
      {paths[name]}
    </svg>
  )
}
